def scores(hook=8, visual=8, originality=8):
    values = {
        "hook": hook, "clarity": 9, "retention": 8, "fact_confidence": 9,
        "visual_potential": visual, "us_relevance": 9, "originality": originality,
    }
    values["average"] = round(sum(values.values()) / 7, 2)
    return values


def meta(jid, day, slot, category, topic, sources, notes=None, disclaimer="", qs=None):
    return {
        "id": jid, "day": day, "slot": slot, "category": category,
        "content_type": "evergreen", "topic": topic, "sources": sources,
        "pronunciation_notes": notes or [], "quality_scores": qs or scores(),
        "rewritten": False, "disclaimer": disclaimer, "status": "READY",
    }


def graph(jid, title, hook, description, tags, hashtags, thumb, narrations, visuals, reasons, overlays=None):
    durations = [5.5, 6.0, 6.2, 6.3, 6.2, 6.3]
    transitions = ["cut", "cut", "fade", "cut", "fade", "cut"]
    motions = ["zoom_in", "pan_lr", "zoom_out", "zoom_in", "pan_lr", "zoom_out"]
    visual_types = ["dramatic", "real_footage", "data_viz", "subtle", "data_viz", "dramatic"]
    scenes = []
    for i, narration in enumerate(narrations):
        query, intent, alternatives = visuals[i]
        scene = {
            "id": f"s{i+1}", "narration": narration, "duration_sec": durations[i],
            "confidence": "confirmed", "transition_in": transitions[i],
            "keywords": alternatives[:2],
            "visual": {
                "type": "broll", "strategy": "real", "scene_visual_type": visual_types[i],
                "motion": motions[i], "query": query, "visual_intent": intent,
                "broll_keywords": alternatives, "decision_reason": reasons[i],
            },
        }
        if overlays and overlays[i]:
            scene["overlays"] = [{"type": "stat", "text": overlays[i], "y": 0.18}]
        scenes.append(scene)
    return {
        "schema_version": "2.0",
        "meta": {
            "video_id": f"vid_fin_{jid}", "channel_id": "usa_finance", "niche": "usa_finance",
            "title": title, "hook": hook, "description": description,
            "tags": tags, "hashtags": hashtags, "thumbnail_text": thumb,
        },
        "fps": 60, "width": 1080, "height": 1920, "scenes": scenes,
    }


